<script>
(()=>{const q=(s,c=document)=>c.querySelector(s),qa=(s,c=document)=>[...c.querySelectorAll(s)];const menu=q('[data-dr-menu]'),toggle=q('[data-dr-menu-toggle]');toggle?.addEventListener('click',()=>{const open=menu.classList.toggle('is-open');toggle.setAttribute('aria-expanded',open)});qa('[data-dr-menu] a').forEach(a=>a.addEventListener('click',()=>menu?.classList.remove('is-open')));
const hero=q('[data-dr-hero]');if(hero){const slides=qa('[data-dr-slide]',hero),dots=qa('[data-dr-hero-dot]',hero);let current=0;const show=i=>{current=i;slides.forEach((el,n)=>el.classList.toggle('is-active',n===i));dots.forEach((el,n)=>el.classList.toggle('is-active',n===i))};dots.forEach((d,i)=>d.addEventListener('click',()=>show(i)));if(slides.length>1)setInterval(()=>show((current+1)%slides.length),Number(hero.dataset.autoplay)||6500)}
const tabs=q('[data-dr-tabs]');if(tabs)qa('[data-dr-tab]',tabs).forEach(btn=>btn.addEventListener('click',()=>{qa('[data-dr-tab]',tabs).forEach(b=>b.classList.remove('is-active'));btn.classList.add('is-active');qa('[data-dr-product]').forEach(card=>card.hidden=btn.dataset.drTab!=='all'&&card.dataset.drProduct!==btn.dataset.drTab)}));
const quotes=qa('[data-dr-quote]'),quoteDots=qa('[data-dr-quote-dot]');quoteDots.forEach((dot,i)=>dot.addEventListener('click',()=>{quotes.forEach((el,n)=>el.classList.toggle('is-active',n===i));quoteDots.forEach((el,n)=>el.classList.toggle('is-active',n===i))}));
const orderModal=q('[data-dr-order-modal]'),orderForm=q('[data-dr-order-form]');let orderTrigger=null;const closeOrder=()=>{if(!orderModal)return;orderModal.classList.remove('is-open');orderModal.setAttribute('aria-hidden','true');document.body.classList.remove('dr-modal-open');orderTrigger?.focus()};qa('[data-dr-order-open]').forEach(btn=>btn.addEventListener('click',()=>{orderTrigger=btn;orderModal?.classList.add('is-open');orderModal?.setAttribute('aria-hidden','false');document.body.classList.add('dr-modal-open');setTimeout(()=>q('input[name="name"]',orderModal)?.focus(),80)}));qa('[data-dr-order-close]').forEach(btn=>btn.addEventListener('click',closeOrder));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&orderModal?.classList.contains('is-open'))closeOrder()});orderForm?.addEventListener('submit',()=>{const date=q('[data-dr-order-date]',orderForm)?.value||'Chưa chọn';const time=q('[data-dr-order-time]',orderForm)?.value||'Chưa chọn';const guests=q('[data-dr-order-guests]',orderForm)?.value||'1';const note=q('[data-dr-order-note]',orderForm)?.value?.trim()||'Không có yêu cầu thêm';q('[data-dr-order-summary]',orderForm).value=`Đặt bàn ngày ${date}, lúc ${time}, ${guests} khách`;q('[data-dr-order-message]',orderForm).value=`Ngày đặt: ${date}\nGiờ đến: ${time}\nSố khách: ${guests}\nYêu cầu: ${note}`});})();
</script>
